# Generated by Devo (Lead Developer)
import json
import re
import asyncio
import logging
from enum import Enum
from typing import List, Optional, Dict, Any, Union
from pydantic import BaseModel, Field, validator
from jsonschema import validate as validate_json_schema, ValidationError

# --- Domain Models ---

class ActionRecommendation(str, Enum):
    PASS = "PASS"
    RETRY_WITH_PROMPT = "RETRY_WITH_PROMPT"
    HARD_FAIL = "HARD_FAIL"

class ValidationProfile(str, Enum):
    STRICT_JSON = "STRICT_JSON"
    TECHNICAL_DOC = "TECHNICAL_DOC"
    CODE_PROD = "CODE_PROD"

class Violation(BaseModel):
    code: str
    message: str
    location: Optional[str] = None

class ValidationResult(BaseModel):
    is_valid: bool
    confidence_score: float = Field(..., ge=0.0, le=1.0)
    violations: List[Violation]
    sanitized_output: Any
    action_recommendation: ActionRecommendation

# --- Core Implementation ---

class OutputValidatorSkill:
    """
    OutputValidatorSkill: A high-performance quality assurance gate for Swarm OS.
    Implements a 4-stage pipeline: Syntactic -> Constraint -> Semantic -> Sanitization.
    """

    HALLUCINATION_MARKERS = [
        r"as an ai language model",
        r"i don't have personal opinions",
        r"my knowledge cutoff",
        r"i am unable to provide",
    ]

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.logger = logging.getLogger("SwarmOS.OutputValidator")
        
    async def validate(
        self, 
        candidate_output: str, 
        validation_profile: ValidationProfile, 
        schema_definition: Optional[Dict] = None, 
        constraints: Optional[List[str]] = None, 
        semantic_anchor: Optional[str] = None
    ) -> ValidationResult:
        """
        Executes the multi-stage gating process to validate LLM output.
        """
        if not candidate_output:
            return self._generate_hard_fail("ERR_EMPTY_RESPONSE", "Candidate output is null or empty.")

        violations = []
        current_output = candidate_output

        try:
            # L1: Syntactic Analysis
            current_output, syntax_violations = await self._stage_l1_syntactic(
                candidate_output, validation_profile, schema_definition
            )
            violations.extend(syntax_violations)

            # L2: Constraint Verification
            constraint_violations = await self._stage_l2_constraints(candidate_output, constraints)
            violations.extend(constraint_violations)

            # L3: Semantic Integrity
            semantic_violations = await self._stage_l3_semantic(candidate_output, semantic_anchor)
            violations.extend(semantic_violations)

            # L4: Sanitization
            sanitized_output = self._stage_l4_sanitize(current_output)

        except Exception as e:
            self.logger.error(f"Critical failure in validation pipeline: {str(e)}")
            return self._generate_hard_fail("SYSTEM_CRITICAL_ERR", str(e))

        # Final Decision Engine
        return self._finalize_result(violations, sanitized_output)

    async def _stage_l1_syntactic(self, output: str, profile: ValidationProfile, schema: Optional[Dict]) -> (Any, List[Violation]):
        violations = []
        processed_output = output

        if profile == ValidationProfile.STRICT_JSON:
            try:
                processed_output = json.loads(output)
                if schema:
                    validate_json_schema(instance=processed_output, schema=schema)
            except json.JSONDecodeError as e:
                violations.append(Violation(code="SYNTAX_ERR", message=f"Invalid JSON: {str(e)}", location="root"))
            except ValidationError as e:
                violations.append(Violation(code="SCHEMA_MISMATCH", message=e.message, location=str(e.path)))
        
        elif profile == ValidationProfile.TECHNICAL_DOC:
            if not output.strip().startswith("#"):
                violations.append(Violation(code="STRUCTURAL_ERR", message="Technical docs must start with a H1 header", location="start"))

        return processed_output, violations

    async def _stage_l2_constraints(self, output: str, constraints: Optional[List[str]]) -> List[Violation]:
        violations = []
        if not constraints:
            return violations

        for pattern in constraints:
            if not re.search(pattern, output, re.IGNORECASE):
                violations.append(Violation(code="CONSTRAINT_ERR", message=f"Required pattern/keyword not found: {pattern}"))
        
        return violations

    async def _stage_l3_semantic(self, output: str, anchor: Optional[str]) -> List[Violation]:
        violations = []
        
        # Detect Hallucination Markers
        for marker in self.HALLUCINATION_MARKERS:
            if re.search(marker, output, re.IGNORECASE):
                violations.append(Violation(code="SEMANTIC_ERR", message="AI self-reference/refusal marker detected"))

        # Ground Truth Alignment (Simple Keyword Overlap for deterministic implementation)
        if anchor:
            anchor_words = set(anchor.lower().split())
            output_words = set(output.lower().split())
            intersection = anchor_words.intersection(output_words)
            overlap_ratio = len(intersection) / len(anchor_words) if anchor_words else 0
            
            if overlap_ratio < 0.3: # Threshold for factual alignment
                violations.append(Violation(code="ALIGNMENT_ERR", message="Output deviates significantly from semantic anchor"))

        return violations

    def _stage_l4_sanitize(self, output: Any) -> Any:
        if isinstance(output, str):
            # Remove trailing whitespace, normalize encoding, strip common LLM artifacts
            return output.strip().replace("\u200b", "")
        return output

    def _finalize_result(self, violations: List[Violation], sanitized_output: Any) -> ValidationResult:
        is_valid = len(violations) == 0
        
        # Heuristic scoring: start at 1.0, deduct for violations
        score = 1.0 - (len(violations) * 0.25)
        score = max(0.0, score)

        # Recommendation Logic
        if is_valid:
            recommendation = ActionRecommendation.PASS
        elif score > 0.5:
            recommendation = ActionRecommendation.RETRY_WITH_PROMPT
        else:
            recommendation = ActionRecommendation.HARD_FAIL

        return ValidationResult(
            is_valid=is_valid,
            confidence_score=score,
            violations=violations,
            sanitized_output=sanitized_output,
            action_recommendation=recommendation
        )

    def _generate_hard_fail(self, code: str, message: str) -> ValidationResult:
        return ValidationResult(
            is_valid=False,
            confidence_score=0.0,
            violations=[Violation(code=code, message=message)],
            sanitized_output=None,
            action_recommendation=ActionRecommendation.HARD_FAIL
        )